import base from './base.js';

/** ESLint flat config for Next.js apps. */
export default [
  // next-env.d.ts and .next/types are generated by the framework on every
  // build. Linting them means fighting the generator.
  { ignores: ['next-env.d.ts', '.next/**', 'next.config.ts'] },
  ...base,
  {
    files: ['**/*.tsx', '**/*.ts'],
    languageOptions: {
      globals: {
        React: 'readonly',
        JSX: 'readonly',
      },
    },
    rules: {
      // Server code logs through the structured logger, client code should
      // not log at all in production builds.
      'no-console': ['error', { allow: ['warn', 'error'] }],
    },
  },
];
